    foreach (var (tx, label, name, mustNotReveal) in new[] { (302, "ENG-WS-13", "second scan request", false), (301, "HMI-01", "first scan request, wrong client", true), (1, "HMI-01", "HMI poll", true), (4242, "X", "missing transaction", true) })
